"""Benchmark for primes.count_primes. Run: python bench.py

Checks correctness on fixed and random sizes against a reference, then times count_primes(1_000_000)
(best of 3 runs). Rules: standard library only, no files, no network, no caching between calls."""
import importlib, random, statistics, sys, time

def reference(n):
    if n < 3:
        return 0
    sieve = bytearray([1]) * n
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(range(i * i, n, i)))
    return sum(sieve)

def main():
    primes = importlib.import_module("primes")
    rng = random.Random()
    sizes = [0, 1, 2, 3, 10, 100, 7919, 7920, 100_000] + [rng.randrange(10_000, 1_500_000) for _ in range(4)]
    for n in sizes:
        got, want = primes.count_primes(n), reference(n)
        if got != want:
            print(f"WRONG count_primes({n}) = {got}, expected {want}")
            return 1
    times = []
    for _ in range(3):
        t0 = time.perf_counter()
        result = primes.count_primes(1_000_000)
        times.append(time.perf_counter() - t0)
        if result != 78498:
            print("WRONG count_primes(1000000) =", result)
            return 1
    print(f"OK correct on {len(sizes) + 3} checks; count_primes(1_000_000) best of 3: {min(times) * 1000:.1f} ms")
    return 0

if __name__ == "__main__":
    sys.exit(main())

