"""Count the primes below n."""


def count_primes(n):
    """Return how many primes p satisfy 2 <= p < n."""
    count = 0
    for k in range(2, n):
        is_prime = True
        for d in range(2, int(k ** 0.5) + 1):
            if k % d == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

