"""Plan a delivery round: start at stop 0 (the depot), visit every stop once, return to 0."""


def solve(points):
    """points: list of (x, y); index 0 is the depot. Return the visiting order as a list of indices,
    starting with 0 and containing every index exactly once (the return to 0 is implied)."""
    return list(range(len(points)))

