"""Put exams into numbered time slots (0, 1, 2, ...)."""


def schedule(exams, students):
    """exams: list of exam ids. students: {student id: [exam ids]}.
    Return {exam id: slot number}. No student may have two exams in the same slot."""
    return {exam: index for index, exam in enumerate(exams)}
